"use client";
import React, { Suspense } from "react";
import HeroSection from "@/components/HeroSection";
import Card from "./Card";
import { contentData9 } from "@/lib/data";
import ServiceAccordion from "./ServiceAccordion";
import ApproachSection from "./ApproachSection";
import WhyChooseSection from "@/components/WhyChooseAST";
import ServicesContact from "./ServicesContact";
import TableOfContent from "./TableOfContent";

export default function ServicesTabs() {
  return (
    <Suspense fallback={<div>Loading services...</div>}>
      <HeroSection
        title={contentData9.hero.title}
        backgroundImage={
          contentData9.hero.backgroundImage || "/images/breadcrum"
        }
        breadcrumbs={[
          {
            label: contentData9.hero.breadcrumbs[0].label,
            href: contentData9.hero.breadcrumbs[0].href,
          },
          {
            label: contentData9.hero.breadcrumbs[1].label,
            href: contentData9.hero.breadcrumbs[1].href,
          },
        ]}
      />
      <div className="w-full container mx-auto px-4 md:px-5  grid grid-cols-1 md:grid-cols-4 gap-8">
        <div className="md:col-span-3">
          <section id="our-services">
            <Card services={contentData9.services} />
          </section>
          <section>
            <ApproachSection
              id="our-approach"
              approach={contentData9.approach}
            />
          </section>
          <section id="why-choose-ast">
            <WhyChooseSection whyChoose={contentData9.whyChoose} />
          </section>
          <section id="faqs" className="w-full px-4 py-10">
            <ServiceAccordion faqs={contentData9.faqs} />
          </section>
          <section id="contact" className="bg-[#2B4EFF] px-4 py-20 mb-5">
            <ServicesContact />
          </section>
        </div>

        <aside className="hidden md:block">
          <TableOfContent />
        </aside>
      </div>
    </Suspense>
  );
}
